import{_ as l,l as s,o as e,c as d,v as r,p as n,x as o,d as i,i as f,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"最大流 Ford–Fulkerson","description":"","frontmatter":{"title":"最大流 Ford–Fulkerson","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/max-flow-ff.md","filePath":"cs/max-flow-ff.md","lastUpdated":1789023840000}'),h={name:"cs/max-flow-ff.md"};function c(u,a,E,F,m,_){const t=s("Mermaid");return e(),d("div",null,[a[1]||(a[1]=r('<h1 id="最大流-ford–fulkerson" tabindex="-1">最大流 Ford–Fulkerson <a class="header-anchor" href="#最大流-ford–fulkerson" aria-label="Permalink to &quot;最大流 Ford–Fulkerson&quot;">​</a></h1><div class="epigraph"><p>源到汇的最大流量等于最小割的容量；沿残量网络增广，直到没有 $s$–$t$ 路。</p><footer>—— 据 Ford and Fulkerson, Maximal Flow Through a Network, 1956；CLRS 第 26 章整理</footer></div><p>上一课<a href="/cs/mst-kruskal-prim">Kruskal 与 Prim</a>处理无向边权之和。流网络是有向边、容量、源 \\(s\\) 与汇 \\(t\\)。本课不重做生成树。缺口是：合法流（容量约束、守恒）的最大值，以及用残量路上的增广来算。本课只钉 Ford–Fulkerson 方法与最大流最小割。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流 \\(f\\) 满足 \\(0\\le f(e)\\le c(e)\\)，除 \\(s,t\\) 外流入等于流出。值 \\(|f|\\) 为 \\(s\\) 净流出。残量图：正向剩余 \\(c-f\\)，反向 \\(f\\)（可退流）。若残量里有 \\(s\\)–\\(t\\) 路，沿路加 \\(\\Delta\\) 仍合法且值增大。没有残量路时，\\(s\\) 侧可达集给出最小割，容量等于 \\(|f|\\)。</p><p>缺口不是线性规划，而是这条组合算法。整数容量时若每次 \\(\\Delta\\ge 1\\)，有限步终止；病态选择可使增广次数随容量指数，Edmonds–Karp 用 BFS 最短增广把迭代变成 \\(O(VE^2)\\)。</p><h3 id="方法不是单一实现" tabindex="-1">方法不是单一实现 <a class="header-anchor" href="#方法不是单一实现" aria-label="Permalink to &quot;方法不是单一实现&quot;">​</a></h3><p>Ford–Fulkerson 是「只要有增广路就增」的框架。最短路增广（Edmonds–Karp）或 Dinic 分层是后继实现。本课证明框架正确 + 最大流 = 最小割；实现默认用 BFS 找路，接上<a href="/cs/bfs-unweighted">无权 BFS</a>。</p><p><span class="marginnote">Ford–Fulkerson 1956。割是顶点划分，容量是前向边容量和。反向边在残量里出现，不是原图多出来的物理管道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(f\\leftarrow 0\\)。循环：在残量上找 \\(s\\)–\\(t\\) 路，算瓶颈 \\(\\Delta\\)，更新 \\(f\\) 与残量。无可增广路则停。割 \\((S,T)\\)：\\(S\\) 为残量中 \\(s\\) 可达。</p>',11)),(e(),n(p,null,{default:o(()=>[f(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%B5%81%20f%22%5D%20--%3E%20Gf%5B%22%E6%AE%8B%E9%87%8F%E7%BD%91%E7%BB%9C%22%5D%0A%20%20Gf%20--%3E%20P%5B%22s%E2%80%93t%20%E5%A2%9E%E5%B9%BF%E8%B7%AF%EF%BC%9F%22%5D%0A%20%20P%20--%3E%7C%22%E6%9C%89%22%7C%20AUG%5B%22%E6%B2%BF%E8%B7%AF%E5%8A%A0%20%CE%94%22%5D%0A%20%20AUG%20--%3E%20F%0A%20%20P%20--%3E%7C%22%E6%97%A0%22%7C%20MIN%5B%22S%3D%E5%8F%AF%E8%BE%BE%E9%9B%86%EF%BC%8C%E6%9C%80%E5%B0%8F%E5%89%B2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>有理容量有限终止；无理容量可无限，主干用整数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>守恒使任意割的净流等于 \\(|f|\\)，故 \\(|f|\\le\\) 任何割容量。增广结束时 \\(|f|\\) 达到某割，故最大。二分图匹配可化成单位容量网络，本课点名：最大匹配 = 最大流，不写匈牙利。</p><p>不要把 MST 的割与流的割混名：一个选边权最小连通，一个是容量之和最小的 \\(s\\)–\\(t\\) 划分。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写费用流、不写推送重标。多源多汇加超级源汇即可。容量随输入指数时要小心增广次数；Edmonds–Karp 给出多项式。下一课离开图，进入串匹配。</p><p>后课默认：最大流 = 反复增广；最大流最小割；整数容量 + 最短增广多项式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>残量增广直到无 \\(s\\)–\\(t\\) 路；此时流最大、割最小。</li><li>框架叫 Ford–Fulkerson；BFS 增广即 Edmonds–Karp。</li><li>整数容量保证终止。</li><li>出处：Ford and Fulkerson, 1956；CLRS 第 26 章。</li></ul>',9))])}const A=l(h,[["render",c]]);export{k as __pageData,A as default};
